<script setup>
import{computed,nextTick,onMounted,onBeforeUnmount,ref,shallowRef,watchEffect}from'vue';
import{endpoint,monthView,navigate,parseAlmanac,todayKey,validateSettings}from'./calendar-model.js';
import{readAlmanac}from'./content-client.js';
const props=defineProps({host:Object,initialSettings:Object});
const settings=ref(validateSettings(props.initialSettings)),cursor=ref(new Date()),today=ref(todayKey()),data=shallowRef({records:new Map()}),selected=shallowRef(null),dialog=ref(),draft=ref({}),loading=ref(false),saving=ref(false),error=ref(''),saveError=ref('');
let alive=true,timer,generation=0;
const calendar=computed(()=>monthView(cursor.value,settings.value.firstDayOfWeek,today.value,data.value.records));
const theme=computed(()=>({'--widget-primary-color':settings.value.primaryColor,'--widget-background-color':settings.value.background,'--widget-color':settings.value.foreground,'--widget-border-radius':settings.value.radius+'px','--widget-font-size':settings.value.fontSize+'px'}));
watchEffect(()=>{if(typeof document!=='undefined')document.documentElement.style.setProperty('--widget-font-size',settings.value.fontSize+'px');});
const status=computed(()=>props.host.preview?'预览 · 不读取在线黄历':loading.value?'正在读取黄历':error.value?(data.value.records.size?'黄历读取失败，保留上次数据：':'黄历读取失败：')+error.value:data.value.fetchedAt===undefined?'':calendar.value.missing?`本月${calendar.value.missing}天黄历未提供`:''),selectedRecord=computed(()=>selected.value?data.value.records.get(selected.value.toYmd()):null);
async function refresh(forceRefresh=false){if(props.host.preview||loading.value||!alive)return;loading.value=true;const stamp=++generation;try{const result=parseAlmanac(await readAlmanac(props.host,forceRefresh));if(alive&&stamp===generation){data.value=result;error.value='';}}catch(reason){if(alive&&stamp===generation)error.value=String(reason?.message||reason);}finally{if(alive&&stamp===generation)loading.value=false;}}
function move(delta){cursor.value=navigate(cursor.value,delta);}
function checkDate(now=Date.now()){const key=todayKey(now);if(key!==today.value){today.value=key;cursor.value=new Date(now);void refresh(true);}}
function openDay(day){if(day.almanac)selected.value=day.solar;}
function open(){draft.value={...settings.value};saveError.value='';dialog.value.showModal();}
async function save(){if(props.host.preview||saving.value)return;saving.value=true;saveError.value='';try{const next=validateSettings({...draft.value,firstDayOfWeek:Number(draft.value.firstDayOfWeek),fontSize:Number(draft.value.fontSize),radius:Number(draft.value.radius)});for(const key of ['primaryColor','background','foreground'])if(!CSS.supports('color',next[key]))throw new Error('颜色格式无效');const result=validateSettings(await props.host.request('settings.update',next));if(alive){settings.value=result;dialog.value.close();}}catch(reason){if(alive)saveError.value='设置未保存：'+String(reason?.message||reason);}finally{saving.value=false;}}
function dispose(){alive=false;generation++;clearInterval(timer);}
onBeforeUnmount(dispose);
onMounted(async()=>{await props.host.ready();if(!alive)return;timer=setInterval(checkDate,1000);await refresh();if(!props.host.preview&&new URLSearchParams(location.search).get('verify')==='widgetjs')await verifySession();});
async function verifySession(){
  if(error.value||!data.value.records.size)throw new Error('原黄历接口未通过：'+error.value);
  const old=await props.host.request('storage.get'),previous=old.verification,label=props.host.instanceId.slice(0,8),background='#'+props.host.instanceId.replaceAll('-','').slice(0,6);let invalidSaveRejected=previous?.invalidSaveRejected===true;
  if(!previous?.uiVerified){open();await nextTick();const before=JSON.stringify(await props.host.request('settings.get'));draft.value.firstDayOfWeek=2;await save();invalidSaveRejected=JSON.stringify(await props.host.request('settings.get'))===before&&saveError.value.includes('未保存');draft.value.firstDayOfWeek=0;draft.value.background=background;draft.value.radius=12;draft.value.fontSize=16;await nextTick();document.getElementById('calendar-form').requestSubmit();for(let n=0;n<100&&saving.value;n++)await new Promise(resolve=>setTimeout(resolve,50));if(saving.value||dialog.value.open)throw new Error('日历表单保存未完成：'+saveError.value);}
  await nextTick();const title=calendar.value.title;document.getElementById('calendar-previous').click();await nextTick();const moved=calendar.value.title!==title;document.getElementById('calendar-next').click();await nextTick();const navigationWorks=moved&&calendar.value.title===title;
  const day=calendar.value.weeks.flat().find(day=>!day.outside&&day.almanac);if(!day)throw new Error('原黄历源没有本月记录');document.querySelector(`[data-day="${day.key}"]`).click();await nextTick();const detailsOpened=selected.value?.toYmd()===day.key&&document.querySelector('.almanac .suit')!==null;document.getElementById('almanac-close').click();await nextTick();
  const marked=calendar.value.weeks.flat().find(day=>!day.outside&&day.label!==day.solar.getLunar().getDayInChinese());let holidayHighlightWorks=true;if(marked){const originalToday=today.value;today.value=marked.key;await nextTick();holidayHighlightWorks=getComputedStyle(document.querySelector(`[data-day="${marked.key}"] .bottom-text`)).color===getComputedStyle(document.querySelector('.root')).color;today.value=originalToday;await nextTick();}
  const saved=await props.host.request('settings.get'),stylesLoaded=getComputedStyle(document.querySelector('.widget')).borderRadius==='12px'&&getComputedStyle(document.documentElement).fontSize==='16px',imagesLoaded=document.querySelectorAll('.calendar-navigation svg path').length===2&&document.querySelectorAll('.calendar-day').length>=28,configurationSaved=saved.firstDayOfWeek===0&&saved.background===background&&saved.fontSize===16;
  await props.host.request('storage.set',{...old,verification:{uiVerified:stylesLoaded&&imagesLoaded&&configurationSaved&&invalidSaveRejected&&navigationWorks&&detailsOpened&&holidayHighlightWorks,stylesLoaded,imagesLoaded,configurationSaved,invalidSaveRejected,navigationWorks,detailsOpened,holidayHighlightWorks,savedLabel:label,runtimeLoads:(previous?.runtimeLoads??0)+1,renderedText:document.querySelector('.month-title').textContent,source:endpoint,calendarRows:data.value.records.size,calendarFirstDate:data.value.firstDate,calendarLastDate:data.value.lastDate,origin:location.origin}});
}
</script>
<template><main class="widget" :style="theme"><div class="root"><header class="calendar-heading"><div class="calendar-title"><strong class="month-title">{{calendar.title}}</strong><small v-if="calendar.isoWeek!==null">第{{calendar.isoWeek}}周</small></div><div class="btn-group calendar-navigation"><button id="calendar-previous" type="button" class="btn" aria-label="上一月" @click="move(-1)"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m15 18-6-6 6-6"/></svg></button><button id="calendar-next" type="button" class="btn" aria-label="下一月" @click="move(1)"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m9 18 6-6-6-6"/></svg></button></div></header><div class="calendar-weekdays"><span v-for="label in calendar.weekdays" :key="label">{{label}}</span></div><div class="calendar-weeks"><div v-for="(week,index) in calendar.weeks" :key="index" class="calendar-week"><div v-for="day in week" :key="day.key" class="day-wrap" :class="{outside:day.outside}"><button type="button" class="calendar-day" :class="{today:day.today}" :data-day="day.key" :aria-label="day.key+' '+day.label+(day.status===1?' 休':day.status===2?' 班':'')" :title="day.almanac?'点击查看黄历':'黄历源未提供该日期'" @click="openDay(day)"><strong>{{day.day}}</strong><div class="day-bottom" :class="{today:day.today}"><span :class="day.label===day.solar.getLunar().getDayInChinese()?'calendar-lunar':'bottom-text'">{{day.label}}</span></div><span v-if="day.status" class="top-right" :class="{work:day.status===2}">{{day.status===1?'休':'班'}}</span></button></div></div></div><output class="status" role="status" :title="status">{{status}}<button v-if="error&&!loading" type="button" @click="refresh(true)">重试</button></output></div><button class="configure" type="button" aria-label="日历设置" title="日历设置" @click="open">⚙</button><div v-if="selected" class="almanac" role="dialog" aria-label="日期黄历" aria-modal="true"><section class="wrapper"><button id="almanac-close" class="close" type="button" aria-label="关闭黄历" @click="selected=null"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg></button><header class="almanac-heading"><strong>{{selected.getYear()}}年{{selected.getMonth()}}月{{selected.getDay()}}日</strong><span>{{selected.getLunar().toString()}}</span><div class="tags"><span class="tag">{{selected.getXingZuo()}}</span><span class="tag">周{{selected.getWeekInChinese()}}</span></div></header><div v-if="selectedRecord" class="almanac-details"><div class="suit"><strong>宜</strong><p>{{selectedRecord.suit||'未提供'}}</p></div><div class="avoid"><strong>忌</strong><p>{{selectedRecord.avoid||'未提供'}}</p></div></div></section></div><dialog ref="dialog" @cancel="saving&&$event.preventDefault()"><form id="calendar-form" @submit.prevent="save"><h2>日历设置</h2><label>一周开始日<select v-model="draft.firstDayOfWeek"><option :value="0">周日</option><option :value="1">周一</option></select></label><label>背景颜色<input v-model="draft.background" maxlength="80" required></label><label>文字颜色<input v-model="draft.foreground" maxlength="80" required></label><label>主色调<input v-model="draft.primaryColor" maxlength="80" required></label><label>字号<input v-model="draft.fontSize" type="number" min="10" max="40" step="1" required></label><label>圆角<input v-model="draft.radius" type="number" min="0" max="50" step="1" required></label><p class="error" role="status">{{saveError}}</p><footer><button type="button" :disabled="saving" @click="dialog.close()">取消</button><button type="submit" :disabled="host.preview||saving">{{saving?'保存中':'保存'}}</button></footer></form></dialog></main></template>
